import{_ as t,a}from"./chunks/save_searchas.n00Q1NuX.js";import{_ as o,c as n,o as s,ag as r}from"./chunks/framework.Bzez9NG9.js";const i="/space/img/server-log11.png",l="/space/img/transaction-logs.png",g="/space/img/audit-log2.png",b=JSON.parse('{"title":"Logs","description":"Search, filter, analyze, and export IBM Planning Analytics and TM1 server, transaction, and audit logs in SPACE.","frontmatter":{"title":"Logs","description":"Search, filter, analyze, and export IBM Planning Analytics and TM1 server, transaction, and audit logs in SPACE.","keywords":["IBM Planning Analytics","Planning Analytics","TM1","TM1 logs","server log","message log","transaction log","audit log","data changes","security events","Logger","troubleshooting"],"outline":"deep"},"headers":[],"relativePath":"doc/planning-analytics/logs.md","filePath":"doc/planning-analytics/logs.md"}'),d={name:"doc/planning-analytics/logs.md"};function c(p,e,h,u,m,v){return s(),n("div",null,e[0]||(e[0]=[r('<h1 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h1><p>The SPACE <strong>Logs</strong> module brings three important IBM Planning Analytics log types into one place: <strong>server logs</strong>, <strong>transaction logs</strong>, and <strong>audit logs</strong>.</p><p>Use them to investigate TM1 server activity and errors, trace changes to data, review security and configuration events, and answer operational questions without manually working through separate log files.</p><p>All three log types support filtering, saved searches, and export, making it easier to repeat investigations or share the relevant results.</p><p>For SPACE application activity and job events, see <a href="./../configuration/journal.html">Journal</a>.</p><h2 id="server-log" tabindex="-1">Server log <a class="header-anchor" href="#server-log" aria-label="Permalink to &quot;Server log&quot;">​</a></h2><p>Use the <strong>Server log</strong> to investigate TM1 server activity, messages, errors, and user logins.</p><p>Filter by fields such as <strong>Level</strong>, <strong>Logger</strong>, and <strong>Message</strong> to narrow the log to the events relevant to an issue.</p><p><img src="'+i+'" alt="Filter builder" data-zoomable=""></p><p>For example, you can focus on a particular error message, logger, user activity, or time period instead of reviewing the complete server log.</p><h2 id="transaction-log" tabindex="-1">Transaction log <a class="header-anchor" href="#transaction-log" aria-label="Permalink to &quot;Transaction log&quot;">​</a></h2><p>Use the <strong>Transaction log</strong> to trace changes to TM1 data.</p><p>Filter by cube, user, tuple elements, and date to investigate where data changed and help troubleshoot unexpected updates.</p><p><img src="'+l+'" alt="Transaction log" data-zoomable=""></p><p>This is useful when you need to determine what data was changed, where the change occurred, and which user was associated with it.</p><h2 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h2><p>Use the <strong>Audit log</strong> to review Planning Analytics configuration, object, and security events.</p><p>Filter by description, user, object type, and date to focus on the activity you need to investigate.</p><p><img src="'+g+'" alt="Audit log" data-zoomable=""></p><p>Display options such as <strong>Object type</strong>, <strong>Action</strong>, <strong>Element</strong>, and <strong>Consolidation</strong> can be used to simplify the view and focus on relevant details.</p><h2 id="filtering-logs" tabindex="-1">Filtering logs <a class="header-anchor" href="#filtering-logs" aria-label="Permalink to &quot;Filtering logs&quot;">​</a></h2><p>The Logs module provides a flexible filter builder for narrowing large result sets.</p><p>Depending on the selected log, available fields can include <strong>Level</strong>, <strong>Message</strong>, <strong>Logger</strong>, <strong>User</strong>, <strong>Object name/key</strong>, and <strong>Details</strong>.</p><p>You can:</p><ul><li>combine conditions using <strong>Apply all conditions (AND)</strong> or <strong>Apply any condition (OR)</strong>;</li><li>add or remove individual filter conditions;</li><li>adjust the <strong>Time period</strong> before applying more detailed filters.</li></ul><p>Using a focused time range first can make investigations easier when working with large logs.</p><h2 id="saved-searches-and-exports" tabindex="-1">Saved searches and exports <a class="header-anchor" href="#saved-searches-and-exports" aria-label="Permalink to &quot;Saved searches and exports&quot;">​</a></h2><p>Save useful filter combinations when you expect to run the same investigation again.</p><ul><li><strong>Save search / Save search as</strong> — store the current filter configuration.</li><li><strong>Open search</strong> — load a previously saved search.</li><li><strong>Export</strong> — download the filtered results as CSV for offline analysis, sharing, or audit requests.</li></ul><p><img src="'+t+'" alt="Saved searches" data-zoomable=""></p><p><img src="'+a+'" alt="Save search dialog" data-zoomable=""></p><h2 id="updating-log-content" tabindex="-1">Updating log content <a class="header-anchor" href="#updating-log-content" aria-label="Permalink to &quot;Updating log content&quot;">​</a></h2><p>SPACE maintains log content that can be refreshed manually or through scheduled jobs.</p><p>Administrators can update a log under <a href="./../configuration/content.html#updating-content-manually">Settings → Content</a> by selecting the relevant Server, Transaction, or Audit log entry and choosing <strong>Update</strong>.</p><p>Use <a href="./../configuration/jobs.html">Jobs</a> to schedule regular updates when log content should be refreshed automatically.</p>',35)]))}const _=o(d,[["render",c]]);export{b as __pageData,_ as default};
